#include "textile_procedurals.hpp"
#include <iostream>
using namespace garment::textile_procedurals;
int main(){try{Json request;std::cin>>request;Json results=Json::array();for(const auto& q:request["cases"]){try{std::string op=q.at("op");Json result;if(op=="describe")result=describeTextileSurface(q.value("fabric",Json::object()));else if(op=="relief")result=textileRelief(q.at("family"),q.at("u"),q.at("v"));else if(op=="maps"){auto full=makeProceduralTextileMaps(q.value("fabric",Json::object()));Json samples=Json::array();for(const auto& xy:q.at("pixels")){int x=xy[0],y=xy[1],index=y*256+x;Json sample={{"height",full["heights"][index]},{"color",Json::array()},{"normal",Json::array()},{"roughness",Json::array()}};for(int n=0;n<4;n++){sample["color"].push_back(full["colorPixels"][4*index+n]);sample["normal"].push_back(full["normalPixels"][4*index+n]);sample["roughness"].push_back(full["roughnessPixels"][4*index+n]);}samples.push_back(sample);}result={{"family",full["family"]},{"tileCm",full["tileCm"]},{"repeat",full["repeat"]},{"rotation",full["rotation"]},{"samples",samples}};}else throw std::runtime_error("unsupported op");results.push_back({{"ok",true},{"result",result}});}catch(const std::exception& e){results.push_back({{"ok",false},{"error",e.what()}});}}std::cout<<results.dump()<<'\n';}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
